// Normaliza y estructura los datos del webhook para los nodos downstream
const item = $input.first().json;
const body = $('Receive Webhook Data').first().json.body || {};

// Limpiar y parsear budget
const budgetRaw = body.budget || '';
const budget = parseFloat(budgetRaw.replace(/[^0-9.]/g, '')) || 0;

// Normalizar technologies (puede llegar como array o string)
const technologies = Array.isArray(body.technologies)
  ? body.technologies.join(', ')
  : String(body.technologies || '');

const company = body.company || body.partner_name || '';

// contact_name: preferir campo explícito del formulario sobre el nombre genérico del lead
const contactName = body.contact_name || body.client_name || body.name || '';

// Extraer hint de empresa desde el dominio del email cuando company está vacío
const emailRaw = body.email || '';
const emailDomain = emailRaw.split('@')[1] || '';
const domainHint = emailDomain
  .replace(/\.(com|es|net|org|io|eu|co\.uk)$/i, '')
  .trim();
const companyHint = company || domainHint;

// ── Queries Tavily optimizadas ──────────────────────────────────────
// query_person: nombre REAL de la persona + empresa/dominio
// NO usar body.name (suele ser 'Cliente Web' u otro valor genérico del CRM)
const queryPerson = [contactName, companyHint]
  .filter(s => s && s.toLowerCase() !== 'cliente web' && s.length > 1)
  .join(' ')
  .trim();

// query_company: dominio completo para máxima especificidad
const queryCompany = [emailDomain]
  .filter(s => s && s.length > 1)
  .join(' ')
  .trim();

return [{
  json: {
    name: body.name || '',
    email: emailRaw,
    email_from: emailRaw,
    phone: body.phone || '',
    company_domain: emailDomain,
    company_name: companyHint,
    contact_name: contactName,
    description_raw: body.description || '',
    budget: budget,
    budget_raw: budgetRaw,
    technologies: technologies,
    pain: body.pain || '',
    website: body.website || '',
    type: 'lead',
    planned_revenue: budget,
    // Queries para Tavily (basadas en datos reales)
    query_person: queryPerson,
    query_company: queryCompany,
    // Metadata
    captured_at: new Date().toISOString(),
    // Config pass-through
    SCORE_THRESHOLD: item.SCORE_THRESHOLD,
    STAGE_ID_NUEVO: item.STAGE_ID_NUEVO,
    TAG_ID_CALIFICADO: item.TAG_ID_CALIFICADO,
    TAG_ID_FRIO: item.TAG_ID_FRIO,
    EMAIL_FROM: item.EMAIL_FROM,
    GEMINI_MODEL: item.GEMINI_MODEL
  }
}];

// El parser nativo ya nos entrega el JSON listo
const parsed = $input.first().json;
const leadData = $('Merge Lead and Tavily Data').first().json;

const SCORE_THRESHOLD = leadData.SCORE_THRESHOLD || 7;
const score = typeof parsed.score === 'number' ? parsed.score : 0;
const isQualified = score >= SCORE_THRESHOLD;

return [{
  json: {
    // IA Analysis
    score: score,
    score_rationale: parsed.score_justification || '',
    completeness: parsed.completeness || {},
    web_presence: parsed.enrichment || {},
    odoo_description: parsed.odoo_description || `<p><strong>Análisis IA (Score: ${score}/10)</strong></p>`,
    email_subject: parsed.email_subject || `[Bitclick] Solicitud recibida — ${leadData.name}`,
    email_body: (parsed.email_body || '').replace(/\{nombre\}/g, leadData.name),
    // Routing
    is_qualified: isQualified,
    tag_id: isQualified ? leadData.TAG_ID_CALIFICADO : leadData.TAG_ID_FRIO,
    tag_name: isQualified ? 'calificado' : 'frío',
    // Lead fields for Odoo
    lead_name: leadData.name,
    lead_email: leadData.email_from,
    lead_phone: leadData.phone,
    lead_company: leadData.company_name, // Restaurado de tu versión ideal
    lead_company_domain: leadData.company_domain,
    lead_contact_name: leadData.contact_name,
    lead_type: leadData.type,
    lead_planned_revenue: leadData.planned_revenue,
    lead_stage_id: leadData.STAGE_ID_NUEVO,
    lead_priority: parsed.priority,
    // Email config
    email_from_address: leadData.EMAIL_FROM
  }
}];

