parameters.jsCode:
const leadData = $('Normalize Lead Data').first().json;
const tavilyRaw = $input.first().json || {};

const tavilyAnswer = tavilyRaw.answer || 'Sin resultados de búsqueda disponibles.';
const tavilyResults = (tavilyRaw.results || [])
  .slice(0, 5)
  .map(r => `${r.title} - ${r.url}\n${(r.content || '').substring(0, 300)}`)
  .join('\n\n');

const tavilyContext = `Resumen: ${tavilyAnswer}\n\nResultados:\n${tavilyResults || 'Ninguno'}`;

return [{
  json: {
    ...leadData,
    tavily_context: tavilyContext
  }
}];

